# ---------------------------------------------------------------- math helpers


@triton.jit
def _acc_tile(
    acc_ap,
    acc_an,
    acc_pn,
    a,
    b,
    c,
    mask,
    eps,
    SWAP: tl.constexpr,
    PMODE: tl.constexpr,
    PGEN: tl.constexpr,
    AXIS: tl.constexpr,
):
    dap = tl.abs(a - b + eps)
    dan = tl.abs(a - c + eps)
    if PMODE == 1:
        acc_ap += tl.sum(tl.where(mask, dap * dap, 0.0), AXIS)
        acc_an += tl.sum(tl.where(mask, dan * dan, 0.0), AXIS)
    elif PMODE == 0:
        acc_ap += tl.sum(tl.where(mask, dap, 0.0), AXIS)
        acc_an += tl.sum(tl.where(mask, dan, 0.0), AXIS)
    elif PMODE == 2:
        acc_ap += tl.sum(tl.where(mask & (dap != 0.0), 1.0, 0.0), AXIS)
        acc_an += tl.sum(tl.where(mask & (dan != 0.0), 1.0, 0.0), AXIS)
    elif PMODE == 3:
        acc_ap = tl.maximum(acc_ap, tl.max(tl.where(mask, dap, 0.0), AXIS))
        acc_an = tl.maximum(acc_an, tl.max(tl.where(mask, dan, 0.0), AXIS))
    elif PMODE == 4:
        acc_ap = tl.minimum(acc_ap, tl.min(tl.where(mask, dap, float("inf")), AXIS))
        acc_an = tl.minimum(acc_an, tl.min(tl.where(mask, dan, float("inf")), AXIS))
    else:
        acc_ap += tl.sum(tl.where(mask, tl.exp2(PGEN * tl.log2(dap)), 0.0), AXIS)
        acc_an += tl.sum(tl.where(mask, tl.exp2(PGEN * tl.log2(dan)), 0.0), AXIS)

    if SWAP:
        dpn = tl.abs(b - c + eps)
        if PMODE == 1:
            acc_pn += tl.sum(tl.where(mask, dpn * dpn, 0.0), AXIS)
        elif PMODE == 0:
            acc_pn += tl.sum(tl.where(mask, dpn, 0.0), AXIS)
        elif PMODE == 2:
            acc_pn += tl.sum(tl.where(mask & (dpn != 0.0), 1.0, 0.0), AXIS)
        elif PMODE == 3:
            acc_pn = tl.maximum(acc_pn, tl.max(tl.where(mask, dpn, 0.0), AXIS))
        elif PMODE == 4:
            acc_pn = tl.minimum(acc_pn, tl.min(tl.where(mask, dpn, float("inf")), AXIS))
        else:
            acc_pn += tl.sum(tl.where(mask, tl.exp2(PGEN * tl.log2(dpn)), 0.0), AXIS)
    return acc_ap, acc_an, acc_pn


@triton.jit
def _finish(
    acc_ap,
    acc_an,
    acc_pn,
    margin,
    SWAP: tl.constexpr,
    PMODE: tl.constexpr,
    PGEN: tl.constexpr,
):
    if PMODE == 1:
        dap = tl.sqrt(acc_ap)
        dan = tl.sqrt(acc_an)
        if SWAP:
            dpn = tl.sqrt(acc_pn)
    elif PMODE == 5:
        dap = tl.exp2((1.0 / PGEN) * tl.log2(acc_ap))
        dan = tl.exp2((1.0 / PGEN) * tl.log2(acc_an))
        if SWAP:
            dpn = tl.exp2((1.0 / PGEN) * tl.log2(acc_pn))
    else:
        dap = acc_ap
        dan = acc_an
        if SWAP:
            dpn = acc_pn
    if SWAP:
        dan = tl.minimum(dan, dpn)
    loss = margin + dap - dan
    return tl.where(loss < 0.0, 0.0, loss)


