# combines the split-feature accumulators of one output tile
@triton.jit
def _combine_kernel(
    buf_ptr,
    out_ptr,
    part_ptr,
    nrows,
    nptiles,
    NSPLIT,
    size,
    margin,
    SWAP: tl.constexpr,
    PMODE: tl.constexpr,
    PGEN: tl.constexpr,
    RED: tl.constexpr,
    BLOCK_P: tl.constexpr,
):
    pid = tl.program_id(0)
    p = pid * BLOCK_P + tl.arange(0, BLOCK_P)
    pmask = p < nrows
    if PMODE == 4:
        acc_ap = tl.full([BLOCK_P], float("inf"), tl.float32)
        acc_an = tl.full([BLOCK_P], float("inf"), tl.float32)
        acc_pn = tl.full([BLOCK_P], float("inf"), tl.float32)
    else:
        acc_ap = tl.zeros([BLOCK_P], tl.float32)
        acc_an = tl.zeros([BLOCK_P], tl.float32)
        acc_pn = tl.zeros([BLOCK_P], tl.float32)
    for s in range(0, NSPLIT):
        idx = (s * nptiles + pid) * BLOCK_P + tl.arange(0, BLOCK_P)
        vap = tl.load(buf_ptr + idx, mask=pmask, other=0.0)
        van = tl.load(buf_ptr + idx + size, mask=pmask, other=0.0)
        if PMODE == 3:
            acc_ap = tl.maximum(acc_ap, vap)
            acc_an = tl.maximum(acc_an, van)
        elif PMODE == 4:
            acc_ap = tl.minimum(acc_ap, vap)
            acc_an = tl.minimum(acc_an, van)
        else:
            acc_ap += vap
            acc_an += van
        if SWAP:
            vpn = tl.load(buf_ptr + idx + 2 * size, mask=pmask, other=0.0)
            if PMODE == 3:
                acc_pn = tl.maximum(acc_pn, vpn)
            elif PMODE == 4:
                acc_pn = tl.minimum(acc_pn, vpn)
            else:
                acc_pn += vpn
    loss = _finish(acc_ap, acc_an, acc_pn, margin, SWAP=SWAP, PMODE=PMODE, PGEN=PGEN)
    if RED == 0:
        tl.store(out_ptr + p, loss.to(out_ptr.dtype.element_ty), mask=pmask)
    else:
        tl.store(
            part_ptr + pid + tl.arange(0, 1),
            tl.sum(tl.where(pmask, loss, 0.0), 0, keep_dims=True),
        )


@triton.jit
def _final_kernel(
    part_ptr,
    out_ptr,
    G,
    inv_rows,
    MEAN: tl.constexpr,
    BLOCK: tl.constexpr,
):
    offs = tl.arange(0, BLOCK)
    acc = tl.zeros([1], tl.float32)
    for s in range(0, G, BLOCK):
        idx = s + offs
        v = tl.load(part_ptr + idx, mask=idx < G, other=0.0)
        acc += tl.sum(v, 0, keep_dims=True)
    if MEAN:
        acc = acc * inv_rows
    tl.store(out_ptr + tl.arange(0, 1), acc.to(out_ptr.dtype.element_ty))


# ---------------------------------------------------------------- host wrapper

_TINY_ELEMS = 65536
_MIN_PROGS = 128
_TARGET_PROGS = 128
_CSPLIT_MIN = 256
_MAX_NSPLIT = 512
_FINAL_BLOCK = 1024


def triplet_margin_loss(
    anchor,
    positive,
    negative,
    margin=1.0,
    p=2,
    eps=1e-06,
    swap=False,
    reduction=1,
):
    if isinstance(reduction, str):
        reduction = {"none": 0, "mean": 1, "sum": 2}[reduction]
    reduction = int(reduction)

    da = anchor.dtype
    if da is not positive.dtype or da is not negative.dtype:
        out_dtype = torch.promote_types(
            torch.promote_types(da, positive.dtype), negative.dtype
        )
        anchor = anchor.to(out_dtype)
        positive = positive.to(out_dtype)
        negative = negative.to(out_dtype)
    else:
        out_dtype = da

    sa = anchor.shape
    if sa != positive.shape or sa != negative.shape:
        anchor, positive, negative = torch.broadcast_tensors(anchor, positive, negative)
        sa = anchor.shape

    if not (
        anchor.is_contiguous() and positive.is_contiguous() and negative.is_contiguous()
    ):
        anchor = anchor.contiguous()
        positive = positive.contiguous()
        negative = negative.contiguous()

    nd = anchor.dim()
    if nd >= 2:
        C = sa[1]
        R = 1
        for k in range(2, nd):
            R *= sa[k]
        nrows = sa[0] * R
        out_shape = (sa[0],) + tuple(sa[2:])
    elif nd == 1:
        C = sa[0]
        R = 1
        nrows = 1
        out_shape = ()
    else:
        C = 1
        R = 1
        nrows = 1
        out_shape = ()

    pf = float(p)
    if pf == 1.0:
        pmode = 0
        pgen = 1.0
    elif pf == 2.0:
        pmode = 1
        pgen = 2.0
    elif pf == 0.0:
        pmode = 2
        pgen = 0.0
    elif pf == _INF:
        pmode = 3
        pgen = _INF
    elif pf == -_INF:
        pmode = 4
        pgen = -_INF
    else:
        pmode = 5
        pgen = pf

    if R > 1:
        BP = min(512, max(32, triton.next_power_of_2(R)))
        BC = max(1, min(16, 2048 // BP))
    else:
        # inner path: BLOCK_P fixes only the grid; the tile width is picked by
        # the autotuner over BLOCK_C / num_warps.
        if C > 0:
            BC = min(2048, triton.next_power_of_2(C))
        else:
            BC = 64
        BP = max(1, min(32, 2048 // BC))
        if nrows > 0:
            BP = min(BP, triton.next_power_of_2(nrows))

    nptiles = triton.cdiv(nrows, BP)
    elems = nrows * C
    nsplit = 1
    split = False
    if elems > _TINY_ELEMS and nptiles <= _MIN_PROGS and C >= _CSPLIT_MIN:
        nsplit = min(_MAX_NSPLIT, max(2, _TARGET_PROGS // nptiles), C // 256)
        split = nsplit >= 2
    single = (not split) and (elems <= _TINY_ELEMS or nptiles == 1)

    dev = anchor.device
    sw = bool(swap)
    mgn = float(margin)
    ep = float(eps)

    if reduction == 0:
        main_out = torch.empty(out_shape, dtype=out_dtype, device=dev)
        inv_rows = 1.0
    else:
        main_out = torch.empty((), dtype=out_dtype, device=dev)
        if reduction == 1:
            inv_rows = (1.0 / nrows) if nrows else _INF
        else:
            inv_rows = 1.0

    if nrows == 0:
        if reduction == 0:
            return main_out
        scratch = torch.empty((1,), dtype=torch.float32, device=dev)
        _final_kernel[(1,)](
            scratch, main_out, 0, inv_rows, MEAN=(reduction == 1), BLOCK=1
        )
        return main_out

    grid1 = 1 if single else nptiles
    buf = main_out
    chunk = C
    size = 0
    if split:
        chunk = triton.cdiv(C, nsplit)
        size = nsplit * nptiles * BP
        buf = torch.empty((3 * size,), dtype=torch.float32, device=dev)
    elif reduction != 0 and not single:
        buf = torch.empty((nptiles,), dtype=torch.float32, device=dev)

    if single:
        # one program performs the whole reduction: keep this latency-bound
        # path free of the autotuner lookup and on a fixed config
        kern = _outer_body if R > 1 else _inner_body
        kern[(1, 1)](
            anchor,
            positive,
            negative,
            main_out,
            buf,
            nrows,
            C,
            R,
            chunk,
            size,
            ep,
            mgn,
            inv_rows,
            SWAP=sw,
            PMODE=pmode,
            PGEN=pgen,
            RED=reduction,
            SPLIT=split,
            SINGLE=single,
            BLOCK_P=BP,
            BLOCK_C=BC,
            num_warps=4,
        )
    else:
        kern = _outer_kernel if R > 1 else _inner_kernel
        kern[(grid1, nsplit)](
            anchor,
            positive,
            negative,
            main_out,
            buf,
            nrows,
            C,
            R,
            chunk,
            size,
            ep,
            mgn,
            inv_rows,
            SWAP=sw,
            PMODE=pmode,
            PGEN=pgen,
            RED=reduction,
            SPLIT=split,
            SINGLE=single,
            BLOCK_P=BP,
        )

    if reduction == 0:
        if split:
            _combine_kernel[(nptiles,)](
                buf,
                main_out,
                main_out,
                nrows,
                nptiles,
                nsplit,
                size,
                mgn,
                SWAP=sw,
                PMODE=pmode,
                PGEN=pgen,
                RED=0,
                BLOCK_P=BP,
            )
        return main_out

    if split:
        ppart = torch.empty((nptiles,), dtype=torch.float32, device=dev)
        _combine_kernel[(nptiles,)](
            buf,
            main_out,
            ppart,
            nrows,
            nptiles,
            nsplit,
            size,
            mgn,
            SWAP=sw,
            PMODE=pmode,
            PGEN=pgen,
            RED=reduction,
            BLOCK_P=BP,
        )
        _final_kernel[(1,)](
            ppart,
            main_out,
            nptiles,
            inv_rows,
            MEAN=(reduction == 1),
            BLOCK=_FINAL_BLOCK,
        )
    elif not single:
        _final_kernel[(1,)](
            buf,
            main_out,
            nptiles,
            inv_rows,
            MEAN=(reduction == 1),
            BLOCK=_FINAL_BLOCK,
        )
    return main_out
